"""gen_npcs.py's site and seen layers and --relayer, on a tiny Trainers.lua written here.

Run: python -m unittest discover -s tools/tests -v
"""
import json
import sys
import tempfile
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import gen_npcs as G  # noqa: E402

TRAINERS = "\n".join([
    "-- GENERATED by tools/gen_npcs.py: do not edit.",
    "-- A header line the relayer keeps.",
    "local _, ns = ...",
    "ns.Data = ns.Data or {}",
    "",
    'ns.Data.trainersMeta = { version = 1, build = "1.60.1.1", classicSource = "test" }',
    "ns.Data.trainers = {",
    '\t{ id = 1, name = "Una", map = 1456, x = 41.5, y = 42.6, place = "Thunder Bluff", role = "trainer", '
    'trains = "Leatherworking", skill = 165, rank = "artisan", tag = "Artisan Leatherworker", faction = "H", '
    "classic = true },",
    '\t{ id = 2, name = "Una", map = 1456, x = 50, y = 50, place = "Thunder Bluff", role = "trainer", '
    'trains = "Cooking", skill = 185, faction = "H", classic = true },',
    '\t{ id = 3, name = "Jarael", map = 2652, place = "Shen\'dralas", role = "trainer", trains = "Leatherworking", '
    'skill = 165, tag = "Leatherworking", faction = "B", nopos = true },',
    '\t{ id = 4, name = "Thuwd", map = 1454, x = 63.4, y = 45.4, place = "Orgrimmar", role = "trainer", '
    'trains = "Leatherworking", skill = { 165, 393 }, tag = "Skinning Trainer", faction = "H", classic = true },',
    '\t{ id = 5, name = "Wulan", map = 1443, x = 26.2, y = 69.8, place = "Desolace", role = "recipes", '
    "recipes = { 16072 }, sells = { 16072 }, limited = { [16072] = 1 }, classic = true },",
    "}",
    "",
])

SITE = {"npcs": {
    "una": {"name": "Una", "map": 1456, "x": 41.7, "y": 42.6, "rank": "expert", "skillLine": 165,
            "ranks": [{"rank": "expert", "skill": 125, "level": 20, "cost": 5000}]},
    "jarael": {"name": "Jarael", "map": 2652, "x": 42.6, "y": 78.1, "rank": None, "ranks": [], "skillLine": 165},
    "thuwd": {"name": "Thuwd", "map": 1454, "x": 63.5, "y": 45.5, "rank": None, "ranks": [], "skillLine": 165},
    "wulan": {"name": "Wulan", "map": 1443, "x": 26.1, "y": 69.7, "rank": None, "ranks": [], "skillLine": 185},
}}


class Relayer(unittest.TestCase):
    def setUp(self):
        self.dir = tempfile.TemporaryDirectory()
        self.path = Path(self.dir.name, "Trainers.lua")
        self.path.write_text(TRAINERS, encoding="utf-8", newline="\n")

    def tearDown(self):
        self.dir.cleanup()

    def lines(self, text):
        return {int(line.split("id = ")[1].split(",")[0]): line for line in text.splitlines()
                if line.startswith("\t{ id = ")}

    def test_without_layers_the_file_comes_back_byte_for_byte(self):
        text, info = G.relayer(self.path, {}, {}, [])
        self.assertEqual(text, TRAINERS)
        self.assertEqual((info["rows"], info["matched"]), (5, []))

    def test_site_layer(self):
        text, info = G.relayer(self.path, SITE["npcs"], {}, [])
        rows = self.lines(text)
        # matched by name and skill line: the Cooking "Una" is left alone, Wulan is not a trainer
        self.assertEqual(rows[1], '\t{ id = 1, name = "Una", map = 1456, x = 41.7, y = 42.6, place = "Thunder Bluff", '
                         'role = "trainer", trains = "Leatherworking", skill = 165, rank = "expert", ranks = { { '
                         'rank = "expert", skill = 125, level = 20, cost = 5000 } }, tag = "Artisan Leatherworker", '
                         'faction = "H", site = true },')
        old = self.lines(TRAINERS)
        self.assertEqual(rows[2], old[2])
        self.assertEqual(rows[5], old[5])
        # a nopos row gains a position; no site rank keeps the row's own (none here)
        self.assertIn("map = 2652, x = 42.6, y = 78.1, place = \"Shen'dralas\"", rows[3])
        self.assertNotIn("nopos", rows[3])
        self.assertIn("skill = { 165, 393 }", rows[4])  # a skill list matches its lines
        self.assertIn("site = true", rows[4])
        self.assertEqual(info["unmatched"], ["wulan"])
        self.assertTrue(text.startswith("-- GENERATED by tools/gen_npcs.py: do not edit.\n-- A header line"))

    def test_seen_beats_site_for_the_position(self):
        seen = {"1": {"map": 1456, "x": 40.0, "y": 40.0}}
        text, info = G.relayer(self.path, SITE["npcs"], seen, [])
        una = self.lines(text)[1]
        self.assertIn("x = 40, y = 40", una)
        self.assertIn('rank = "expert"', una)  # the site rank still applies
        self.assertIn("seen = true", una)
        self.assertNotIn("site = true", una)
        self.assertEqual(info["seen"], 1)

    def test_main_relayer_and_bad_site_file(self):
        site = Path(self.dir.name, "site.json")
        site.write_text(json.dumps(SITE), encoding="utf-8")
        out = Path(self.dir.name, "out.lua")
        args = ["--relayer", "--in", str(self.path), "--out", str(out), "--site", str(site),
                "--seen", str(Path(self.dir.name, "absent.json")), "--places", str(Path(self.dir.name, "none.lua"))]
        self.assertEqual(G.main(args), 0)
        self.assertIn('rank = "expert"', out.read_text(encoding="utf-8"))
        site.write_text(json.dumps({"npcs": {"x": {"name": "X"}}}), encoding="utf-8")
        self.assertEqual(G.main(args), 2)  # a site row without a position is a broken link

    def test_full_build_needs_its_inputs(self):
        with self.assertRaises(SystemExit):
            G.main(["--out", "x.lua"])


if __name__ == "__main__":
    unittest.main()
